<details>
<summary>Reproduce the local runtime proof</summary>

Use separate built trees at the two commits above, named `base/` and `source/`, with their own dependencies. Save the following two external proof files under sibling `evidence/`. The fixture requires no provider account or real API key. Use two free loopback ports and run each invocation once with a fresh output directory.

```sh
export OPENCLAW_PROOF_WORK="$PWD"
export OPENCLAW_PROOF_NODE="$(command -v node)"
export OPENCLAW_PROOF_PORTS='[19181,19182]'
"$OPENCLAW_PROOF_NODE" evidence/proof.mjs base causal
"$OPENCLAW_PROOF_NODE" evidence/proof.mjs source causal
```

The harness launches this actual product command in each tree and sends HTTP requests, including `{"tool":"memory_recall","args":{"query":"synthetic preference"},"sessionKey":"agent:main:runtime-deadline-proof"}`, to `/tools/invoke`:

```sh
node --import ../evidence/observe.mjs openclaw.mjs gateway run
```

`evidence/observe.mjs`:

```js
// Test-only runtime observations/delays. No source or build files are edited.
import { registerHooks } from 'node:module';
import { readFileSync, appendFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';
import { isMainThread } from 'node:worker_threads';

if (isMainThread) {
  const root = process.env.PROOF_TREE;
  const control = () => JSON.parse(readFileSync(process.env.PROOF_CONTROL, 'utf8'));
  const log = (event, data = {}) => appendFileSync(process.env.PROOF_EVENTS,
    JSON.stringify({ event, case: control().case, pid: process.pid, monotonicMs: performance.now(), ...data }) + '\n');
  globalThis.__proofEmbedding = async promise => {
    const value = await promise; // Actual OpenAI-compatible HTTP request and response.
    const { embedDelay = 0 } = control();
    log('embedding_response', { delayMs: embedDelay });
    if (embedDelay) await delay(embedDelay); // Transport has completed; deliberately late completion.
    log('embedding_release');
    return value; // Never replace the response/vector/error or admission result.
  };
  const hook = registerHooks({ load(url, context, next) {
    const result = next(url, context);
    if (url.startsWith(pathToFileURL(root + '/dist/extensions/memory-lancedb/.setup/').href) && /\/embeddings-[^/]+\.mjs$/.test(url)) {
      const original = String(result.source);
      const needle = 'await this.postEmbedding(text, dimensions, timeoutMs)';
      if (original.split(needle).length !== 2) throw new Error('Embedding observation anchor mismatch');
      log('module_observed', { url, sha256: createHash('sha256').update(original).digest('hex'), insertion: 'await original HTTP promise, delay completion, return original value' });
      return { ...result, source: original.replace(needle, 'await globalThis.__proofEmbedding(this.postEmbedding(text, dimensions, timeoutMs))') };
    }
    return result;
  }});
  const { MemoryDB } = await import(pathToFileURL(root + '/dist/extensions/memory-lancedb/lancedb-store.js'));
  const { loadLanceDbModule } = await import(pathToFileURL(root + '/dist/extensions/memory-lancedb/lancedb-runtime.js'));
  const lance = await loadLanceDbModule();
  const restorations = [];
  const wrap = (object, name, make) => {
    const original = object[name];
    object[name] = make(original);
    restorations.push(() => object[name] = original);
  };
  wrap(MemoryDB.prototype, 'search', original => async function(...args) {
    log('search_enter', { agentId: args[0], timeoutMs: args[4]?.timeoutMs, dbPath: this.dbPath });
    try { const rows = await original.apply(this, args); log('search_return', { rows: rows.length }); return rows; }
    catch (error) { log('search_error', { message: error.message }); throw error; }
  });
  wrap(MemoryDB.prototype, 'ensureInitialized', original => async function(...args) {
    const start = performance.now();
    await original.apply(this, args); // Real init/checkoutLatest still runs.
    const { prepDelay = 0 } = control();
    if (prepDelay) { log('preparation_delay', { delayMs: prepDelay }); await delay(prepDelay); }
    log('preparation_complete', { elapsedMs: performance.now() - start });
  });
  wrap(lance.VectorQuery.prototype, 'toArray', original => async function(...args) {
    log('native_dispatch', { options: args[0] ?? null });
    try { const rows = await original.apply(this, args); log('native_return', { rows: rows.length }); return rows; }
    catch (error) { log('native_error', { message: error.message }); throw error; }
  });
  log('observer_ready', { root, node: process.version, lancedb: '0.41.0' });
  process.once('exit', () => {
    for (const restore of restorations.reverse()) restore();
    hook.deregister(); delete globalThis.__proofEmbedding;
    log('observer_restored');
  });
}
```

`evidence/proof.mjs`:

```js
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
