Save this script as `real-transport.mjs`. It reads both pinned Git revisions, compiles the actual client and socket helper, verifies the helper source hash, runs real processes through authenticated temporary local sockets, checks the returned receipts, and removes its temporary sockets and bundles. It changes no installed app or repository source.

```js
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { execFileSync, spawn } from 'node:child_process';
import { once } from 'node:events';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const repo = path.resolve(process.argv[2]);
const base = '5c894c71b889408c0bf583ae4aa08e36129ab3a4';
const head = '30170786a7ebbcdc7a93ea4d570c5fe386f0494f';
const require = createRequire(path.join(repo, 'package.json'));
const esbuild = require('esbuild');
const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8' }).trimEnd();
const scratch = await fs.mkdtemp(path.join(os.tmpdir(), 'oc-proof-'));
const token = 'synthetic-local-proof-token';
const rows = [];
console.log(JSON.stringify({ event: 'environment', platform: os.platform(), release: os.release(), arch: os.arch(), node: process.version, esbuild: esbuild.version, base, head, entrypoint: 'src/infra/exec-host.ts:requestExecHostViaSocket', realTimers: true, realUnixSockets: true, transportTimeoutOverride: false, peer: 'synthetic HMAC-verifying host that executes the requested /bin/sleep; NOT the signed macOS companion', time: new Date().toISOString() }));

async function build(ref, mode) {
  const dir = path.join(scratch, mode);
  await fs.mkdir(dir);
  for (const name of ['exec-host', 'jsonl-socket']) {
    const file = `src/infra/${name}.ts`;
    await fs.writeFile(path.join(dir, `${name}.ts`), git('show', `${ref}:${file}`));
    console.log(JSON.stringify({ event: 'source', mode, file, blob: git('rev-parse', `${ref}:${file}`) }));
  }
  const dependency = path.join(repo, 'packages/normalization-core/src/number-coercion.ts');
  // Resolve the workspace helper from its actual source; no timer or transport stubs.
  assert.equal(git('rev-parse', `${base}:packages/normalization-core/src/number-coercion.ts`), git('rev-parse', `${head}:packages/normalization-core/src/number-coercion.ts`));
  assert.equal(crypto.createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${(await fs.readFile(dependency)).length}\0`), await fs.readFile(dependency)])).digest('hex'), git('rev-parse', `${head}:packages/normalization-core/src/number-coercion.ts`));
  const out = path.join(dir, 'client.mjs');
  await esbuild.build({ entryPoints: [path.join(dir, 'exec-host.ts')], outfile: out, bundle: true, platform: 'node', format: 'esm', target: 'node24', plugins: [{ name: 'workspace-helper', setup(b) { b.onResolve({ filter: /^@openclaw\/normalization-core\/number-coercion$/ }, () => ({ path: dependency })); } }] });
  return (await import(pathToFileURL(out).href)).requestExecHostViaSocket;
}

async function probe(mode, client, seconds, scenario) {
  const dir = await fs.mkdtemp(path.join(scratch, 'socket-'));
  const socketPath = path.join(dir, 'host.sock');
  const sockets = new Set();
  const children = new Set();
  let peerResolve, peerReject;
  const peerDone = new Promise((resolve, reject) => { peerResolve = resolve; peerReject = reject; });
  let hmacVerified = false;
  const server = net.createServer({ allowHalfOpen: true }, socket => {
    sockets.add(socket);
    socket.on('error', () => {});
    socket.on('close', () => sockets.delete(socket));
    let data = '';
    socket.setEncoding('utf8');
    socket.on('data', chunk => { data += chunk; });
    socket.once('end', () => {
      try {
        const wire = JSON.parse(data.trim());
        assert.equal(wire.type, 'exec');
        assert.equal(wire.hmac, crypto.createHmac('sha256', token).update(`${wire.nonce}:${wire.ts}:${wire.requestJson}`).digest('hex'));
        hmacVerified = true;
        const request = JSON.parse(wire.requestJson);
        assert.deepEqual(request.command, ['/bin/sleep', String(seconds)]);
        assert.equal(request.timeoutMs, 35000);
        const started = performance.now();
        const child = spawn(request.command[0], request.command.slice(1));
        children.add(child);
        let timedOut = false, stdout = '', stderr = '';
        child.stdout.on('data', d => { stdout += d; });
        child.stderr.on('data', d => { stderr += d; });
        const deadline = setTimeout(() => { timedOut = true; child.kill('SIGTERM'); }, request.timeoutMs);
        child.once('error', peerReject);
        child.once('close', (code, signal) => {
          clearTimeout(deadline);
          children.delete(child);
          const result = { ok: true, payload: { exitCode: code ?? (signal === 'SIGTERM' ? 143 : -1), timedOut, success: code === 0 && !timedOut, stdout, stderr } };
          socket.end(JSON.stringify({ type: 'exec-res', ...result }) + '\n');
          peerResolve({ peerElapsedMs: Math.round(performance.now() - started), peerResult: result });
        });
      } catch (error) { peerReject(error); }
    });
  });
  const controller = new AbortController();
  const watchdog = setTimeout(() => controller.abort(), 50000);
  server.listen(socketPath);
  await once(server, 'listening');
  try {
    const started = performance.now();
    // Intentionally no top-level timeoutMs: exercise the production default path.
    const clientResult = await client({ socketPath, token, request: { command: ['/bin/sleep', String(seconds)], timeoutMs: 35000 }, signal: controller.signal });
    const clientElapsedMs = Math.round(performance.now() - started);
    const peer = await peerDone;
    const row = { mode, scenario, transportTimeoutOverride: false, processTimeoutMs: 35000, hmacVerified, clientElapsedMs, ...peer, clientResult };
    console.log(JSON.stringify(row));
    rows.push(row);
    assert.equal(hmacVerified, true);
    assert.equal(peer.peerResult.payload.timedOut, seconds === 60);
    if (mode === 'baseline') {
      assert.equal(clientResult, null);
      assert.ok(clientElapsedMs >= 19000 && clientElapsedMs < peer.peerElapsedMs);
    } else {
      assert.deepEqual(clientResult, peer.peerResult);
      assert.ok(clientElapsedMs > 20000);
    }
  } finally {
    clearTimeout(watchdog);
    controller.abort();
    for (const child of children) child.kill('SIGKILL');
    for (const socket of sockets) socket.destroy();
    await new Promise(resolve => server.close(resolve));
  }
}

try {
  const baseline = await build(base, 'baseline');
  const candidate = await build(head, 'candidate');
  const results = await Promise.allSettled([
    probe('baseline', baseline, 22, 'late-completion'),
    probe('candidate', candidate, 22, 'late-completion'),
    probe('baseline', baseline, 60, 'process-timeout-receipt'),
    probe('candidate', candidate, 60, 'process-timeout-receipt'),
  ]);
  const failures = results.filter(x => x.status === 'rejected');
  console.log(JSON.stringify({ event: 'summary', scenarios: rows.length, passed: results.length - failures.length, failed: failures.length }));
  for (const failure of failures) console.error(String(failure.reason));
  if (failures.length) process.exitCode = 1;
} finally {
  await fs.rm(scratch, { recursive: true, force: true });
