```js
// External test inputs only. No product modules, validators, requests or receipts are replaced.
import dns from 'node:dns';
import dnsPromises from 'node:dns/promises';
import { syncBuiltinESMExports } from 'node:module';
const originalNow = Date.now;
const offset = Number(process.env.PROOF_CLOCK_OFFSET_MS);
if (!Number.isFinite(offset)) throw new Error('Explicit proof clock offset required');
// Only the two explicit temporal consumers use the synthetic protocol epoch.
// Kernel timestamps, database admission, lock renewal and all other owners keep real time.
// This changes a clock input, never a parser/authority/storage/scheduling result.
const clockReceipts = new Set();
Date.now = () => {
  const caller = (new Error().stack ?? '').split('\n')[2] ?? '';
  const selected = /\/(?:gateway-scheduler-|service-mcp-events-)[^/]+\.mjs:/u.test(caller);
  if (selected && !clockReceipts.has(caller)) {
    clockReceipts.add(caller);
    process.stderr.write(JSON.stringify({proofClock:true,caller,realNow:originalNow(),testNow:originalNow()+offset})+'\n');
  }
  return originalNow() + (selected ? offset : 0);
};
const originalLookup = dns.lookup;
const originalPromiseLookup = dnsPromises.lookup;
const answer = [{ address: '93.184.216.34', family: 4 }];
dns.lookup = function(host, options, callback) {
  if (host !== 'events.example.com') return originalLookup.apply(this, arguments);
  if (typeof options === 'function') { callback = options; options = {}; }
  process.stderr.write('PROOF_DNS events.example.com synthetic public A answer\n');
  queueMicrotask(() => options?.all ? callback(null, answer) : callback(null, answer[0].address, 4));
};
dnsPromises.lookup = async function(host, options) {
  if (host !== 'events.example.com') return originalPromiseLookup.apply(this, arguments);
  process.stderr.write('PROOF_DNS events.example.com synthetic public A answer\n');
  return options?.all ? answer : answer[0];
};
syncBuiltinESMExports();
process.stderr.write(JSON.stringify({proofBoundary:true,pid:process.pid,cwd:process.cwd(),execPath:process.execPath,argv:process.argv,realNow:originalNow(),testNow:originalNow()+offset,offset,clockRate:1,timers:'unchanged',dnsHost:'events.example.com'})+'\n');
// Injections are confined to this owned process and its inherited workers. Exit restores the host.
