import { createCliEventHandlers } from "../src/agents/cli-runner/execute-events.js";
import { createCliToolTracking } from "../src/agents/cli-runner/execute-tool-tracking.js";
import type { PreparedCliRunContext } from "../src/agents/cli-runner/types.js";
import { createCliJsonlStreamingParser } from "../src/agents/cli-output-stream.js";

/** Mirrors `MAX_SETTLED_MESSAGING_EVIDENCE_CHARS`, restated so the pre-fix tree runs. */
const SETTLED_EVIDENCE_BUDGET_CHARS = 8 * 1024 * 1024;
/** Mirrors `MAX_REDUCED_MESSAGING_ARG_CHARS` x the 64-entry count cap. */
const REDUCED_ENTRY_SLACK_CHARS = 8 * 1024 * 64;
/**
 * The finding's own numbers. `OPENCLAW_PROOF_SENDS` lowers the count for the
 * "before" run, which really does retain every byte and would otherwise need
 * ~450 MiB of resident heap on a shared machine; any count whose content
 * outgrows the 8 MiB budget reproduces the defect.
 */
const SENDS = Number(process.env.OPENCLAW_PROOF_SENDS ?? 64);
const SEND_CHARS = 7 * 1024 * 1024;
/**
 * Retained heap a bounded run may add. This is corroboration, not the bound:
 * the bound is on retained evidence CHARACTERS, asserted exactly above. What
 * heap has to show is that retention does not scale with the content streamed.
 * The run legitimately keeps its own budgets at once — 8 MiB of settled
 * evidence, the 8 MiB pending-argument allowance, one pending line of up to
 * 8 MiB — plus V8 slack for 455 MiB of transient 7 MiB strings, which is why
 * this is tens of MiB rather than single digits.
 */
const MAX_HEAP_GROWTH_BYTES = 128 * 1024 * 1024;

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) {
    throw new Error(`proof assertion failed: ${message}`);
  }
}

/** Collects garbage without requiring `--expose-gc` on the run command. */
function forceGarbageCollection(): void {
  setFlagsFromString("--expose-gc");
  try {
    const gc = runInNewContext("gc") as () => void;
    gc();
    gc();
  } finally {
    setFlagsFromString("--no-expose-gc");
  }
}

/**
 * Module-level keep-alive. A tracking object held only in a function local is
 * dead once the loop that fed it ends, and V8 collects the retained evidence
 * with it — a flat reading even against a build with no bound at all.
 */
const retainedForMeasurement: unknown[] = [];

const workDir = mkdtempSync(path.join(tmpdir(), "openclaw-proof-160325-"));
const generatorPath = path.join(workDir, "emit-sends.mjs");

function removeWorkDir(): boolean {
  try {
    rmSync(workDir, { recursive: true, force: true });
  } catch {
    return false;
  }
  return !existsSync(workDir);
}

/**
 * The child process. Writes `SENDS` sequentially settled `message` sends, then
 * one duplicate of the last send under a fresh tool-call id (the
 * duplicate-suppression case), then the terminal result. It builds each body
 * itself, so the ~448 MiB never exists in the parent except as pipe chunks.
 */
writeFileSync(
  generatorPath,
  `const SENDS = ${SENDS};
const SEND_CHARS = ${SEND_CHARS};
const body = (index) => index + ":" + "x".repeat(SEND_CHARS);
const start = (toolCallId, index) =>
  JSON.stringify({
    type: "assistant",
    parent_tool_use_id: null,
    message: {
      id: "msg_" + toolCallId,
      content: [
        {
          type: "tool_use",
          id: toolCallId,
          name: "mcp__openclaw__message",
          input: { action: "send", channel: "slack", target: "c" + index, content: body(index) },
        },
      ],
    },
  }) + "\\n";
const settle = (toolCallId) =>
  JSON.stringify({
    type: "user",
    parent_tool_use_id: null,
    message: {
      content: [
        {
          type: "tool_result",
          tool_use_id: toolCallId,
          content: {
            details: {
              deliveryStatus: "sent",
              messageDelivery: {
                status: "settled",
                partialDelivery: false,
                createdThreadIds: [],
              },
            },
          },
        },
      ],
    },
  }) + "\\n";
const write = (text) =>
  new Promise((resolve) => {
    if (process.stdout.write(text)) {
      resolve();
      return;
    }
    process.stdout.once("drain", resolve);
  });
for (let index = 0; index < SENDS; index += 1) {
  await write(start("toolu_" + index, index));
  await write(settle("toolu_" + index));
}
await write(start("toolu_duplicate", SENDS - 1));
await write(settle("toolu_duplicate"));
await write(JSON.stringify({ type: "result", subtype: "success", is_error: false, result: "done" }) + "\\n");
`,
);

const context = buildPreparedCliRunContext({
  runId: "proof-160325",
  sessionKey: "agent:main:slack:channel:c1",
}) as PreparedCliRunContext;
const toolTracking = createCliToolTracking(context);
const handlers = createCliEventHandlers({
  context,
  toolTracking,
  getRunState: () => ({ failed: false, error: undefined }),
});
const parser = createCliJsonlStreamingParser({
  backend: { command: "claude", output: "jsonl", jsonlDialect: "claude-stream-json" },
  providerId: "claude-cli",
  onToolUseStart: handlers.emitParsedToolUseStart,
  onToolResult: handlers.emitParsedToolResult,
});
retainedForMeasurement.push(parser, handlers, toolTracking);

forceGarbageCollection();
const heapBefore = process.memoryUsage().heapUsed;

let streamedChars = 0;
let exhaustedAtChars = 0;
const spawnExit = await new Promise<{ code: number | null; stderr: string }>((resolve, reject) => {
  const child = spawn(process.execPath, [generatorPath], { stdio: ["ignore", "pipe", "pipe"] });
  let stderr = "";
  child.stdout.setEncoding("utf8");
  child.stdout.on("data", (chunk: string) => {
    streamedChars += chunk.length;
    parser.push(chunk);
    if (exhaustedAtChars === 0 && parser.getErrorText() !== null) {
      exhaustedAtChars = streamedChars;
    }
  });
  child.stderr.setEncoding("utf8");
  child.stderr.on("data", (chunk: string) => {
    stderr += chunk;
  });
  child.on("error", reject);
  child.on("close", (code) => resolve({ code, stderr }));
});
parser.finish();

try {
  assert(
    spawnExit.code === 0,
    `the send generator exited ${spawnExit.code}: ${spawnExit.stderr.slice(0, 400)}`,
  );
  assert(
    streamedChars > SENDS * SEND_CHARS,
    `the stream carried only ${streamedChars} chars, so nothing was proved`,
  );
  assert(
    exhaustedAtChars > 0 && exhaustedAtChars < streamedChars,
    "the turn budget was never spent, so this is not the post-budget path the finding is about",
  );

  const retained = handlers.getRetainedStateSizes();
  assert(
    retained.retainedToolArgChars === 0,
    `pending arguments were not refunded (${retained.retainedToolArgChars} chars), so the settled holders are not what is being measured`,
  );

  const evidence = toolTracking.withExecutionEvidence({ text: "" });
  const texts = evidence.messagingToolSentTexts ?? [];
  const targets = evidence.messagingToolSentTargets ?? [];
  const evidenceChars =
    texts.reduce((sum, text) => sum + text.length, 0) + JSON.stringify(targets).length;

  // Delivery facts first: a bound that loses them is not a fix.
  assert(evidence.didSendViaMessagingTool === true, "the settled sends stopped counting as sends");
  assert(
    targets.length === SENDS,
    `expected ${SENDS} distinct settled targets, got ${targets.length}`,
  );
  assert(
    new Set(targets.map((target) => `${target.provider}/${target.to}`)).size === SENDS,
    "distinct sends collapsed into one another, so delivery evidence lost sends",
  );
  assert(
    new Set(texts).size === texts.length,
    "duplicate-suppression failed: the same text is retained twice",
  );
  const last = targets.at(-1);
  assert(
    last?.provider === "slack" && last?.to === `channel:c${SENDS - 1}`,
    `the send past the budget lost its routing facts: ${JSON.stringify(last)}`,
  );

  // The bound itself.
  assert(
    evidenceChars <= SETTLED_EVIDENCE_BUDGET_CHARS + REDUCED_ENTRY_SLACK_CHARS,
    `settled delivery evidence retained ${evidenceChars} chars, over the ${SETTLED_EVIDENCE_BUDGET_CHARS}+${REDUCED_ENTRY_SLACK_CHARS} budget`,
  );

  forceGarbageCollection();
  const heapGrowth = process.memoryUsage().heapUsed - heapBefore;
  assert(
    heapGrowth < MAX_HEAP_GROWTH_BYTES && heapGrowth < streamedChars / 4,
    `retained heap grew ${(heapGrowth / 1024 / 1024).toFixed(1)} MiB after ${(streamedChars / 1024 / 1024).toFixed(1)} MiB of settled sends`,
  );

  console.log(
    `[sequential-settlement] ${SENDS} sends settled one at a time over a real pipe: ` +
      `${(streamedChars / 1024 / 1024).toFixed(1)} MiB streamed, budget spent at ` +
      `${(exhaustedAtChars / 1024 / 1024).toFixed(1)} MiB, pending args refunded to ` +
      `${retained.retainedToolArgChars} chars`,
  );
  console.log(
    `[sequential-settlement] retained settled evidence ${evidenceChars} chars ` +
      `(${(evidenceChars / 1024 / 1024).toFixed(2)} MiB) in ${texts.length} text(s) and ` +
      `${targets.length} target(s); diagnostics ${JSON.stringify({
        settledMessagingEvidenceChars: retained.settledMessagingEvidenceChars,
        reducedSettledMessagingEntries: retained.reducedSettledMessagingEntries,
      })}`,
  );
  console.log(
    `[sequential-settlement] retained heap +${(heapGrowth / 1024 / 1024).toFixed(1)} MiB for ` +
      `${(((SENDS * SEND_CHARS) / 1024 / 1024) | 0)} MiB of settled content; ` +
      `first send's text retained=${texts.includes(`0:${"x".repeat(SEND_CHARS)}`)}, ` +
      `last send's text retained=${texts.includes(`${SENDS - 1}:${"x".repeat(SEND_CHARS)}`)}`,
  );
  console.log("All runtime assertions passed.");
} finally {
  const removed = removeWorkDir();
  console.log(`[cleanup] generator directory removed: ${removed}`);
  if (!removed) {
    process.exitCode = 1;
  }
}
